<script>
  import { createEventDispatcher, onMount } from "svelte";
  import { invoke } from "@tauri-apps/api/core";
  import { t, fmt, currentLang, LANGUAGES } from "./i18n.js";
  import { theme, toggleTheme } from "./theme.js";

  const dispatch = createEventDispatcher();

  // mode: "new" | "restore"
  export let mode = "new";
  const restoring = mode === "restore";

  let step = 1;

  // Step 1 — password
  let password = "";
  let passwordConfirm = "";
  let passwordError = "";

  // Step 2 — seed: generated by the backend, or typed when restoring
  let seedLoading = !restoring;
  let seedGenError = false;
  let generatedSeed = "";
  let importedSeed = "";

  // Restore: approximate wallet creation date, to scan the chain from there
  const thisYear = new Date().getFullYear();
  const YEARS = Array.from({ length: thisYear - 2014 + 1 }, (_, i) => thisYear - i);
  let restoreYear = "";
  let restoreMonth = "";
  let restoreDateUnknown = false;
  $: monthNames = Array.from({ length: 12 }, (_, i) =>
    new Date(Date.UTC(2000, i, 1)).toLocaleString($currentLang, { month: "long", timeZone: "UTC" }));
  $: restoreDateSet = restoreDateUnknown || (restoreYear !== "" && restoreMonth !== "");
  $: restoreFrom = restoreDateUnknown ? 0 : Math.floor(Date.UTC(+restoreYear, +restoreMonth, 1) / 1000);

  // Step 3 — finalize wallet creation
  let finishLoading = false;
  let finishError = "";

  onMount(async () => {
    if (restoring) return;
    try {
      generatedSeed = await invoke("generate_seed");
    } catch (e) {
      seedGenError = true;
    }
    seedLoading = false;
  });

  // Step 3 — backup + seed word verification
  let checkPaperSeed = false;
  let checkPaperPassword = false;
  let checkLimit = false;

  // Seed word challenge — only for a freshly generated seed
  let verifyIndex = Math.floor(Math.random() * 25) + 1;  // 1-based, random
  let verifyInput = "";
  let verifyError = false;
  let verifyPassed = restoring;

  $: normalizedImport = importedSeed.trim().toLowerCase().split(/\s+/).filter(Boolean).join(" ");
  $: importWordCount = normalizedImport ? normalizedImport.split(" ").length : 0;
  $: importSeedValid = importWordCount === 25;
  $: importSeedError = normalizedImport && !importSeedValid ? fmt($t.seedWordCount, { n: importWordCount }) : null;

  $: activeSeed = restoring ? normalizedImport : generatedSeed;
  $: seedWords = activeSeed.split(" ");
  $: expectedWord = seedWords[verifyIndex - 1] || "";

  function checkWord() {
    if (verifyInput.trim().toLowerCase() === expectedWord.toLowerCase()) {
      verifyPassed = true;
      checkPaperSeed = true;
      verifyError = false;
    } else {
      verifyError = true;
      verifyInput = "";
    }
  }

  function validateStep1() {
    passwordError = "";
    if (password.length < 12) { passwordError = $t.passwordTooShort; return false; }
    if (password !== passwordConfirm) { passwordError = $t.passwordMismatch; return false; }
    return true;
  }

  function goStep2() { if (validateStep1()) step = 2; }
  function goStep3() { step = 3; }

  function createError(e) {
    const msg = String(e?.message ?? e);
    if (msg.startsWith("SEED_INVALID")) return $t.seedInvalid;
    if (msg.startsWith("SEED_WORD_COUNT:")) return fmt($t.seedWordCount, { n: msg.split(":")[1] });
    if (msg === "WALLET_EXISTS") return $t.walletExists;
    if (msg === "PASSWORD_TOO_SHORT") return $t.passwordTooShort;
    return msg;
  }

  async function finish() {
    finishLoading = true;
    finishError = "";
    try {
      await invoke("create_wallet", { seed: activeSeed, password, restoreFrom: restoring ? restoreFrom : null });
      dispatch("complete");
    } catch (e) {
      finishError = createError(e);
      finishLoading = false;
    }
  }

  function goBack() {
    if (step === 1) dispatch("back");
    else step -= 1;
  }
</script>

<div class="onboarding">
  <!-- Progress bar -->
  <div class="progress-bar">
    <div class="progress-fill" style="width: {(step / 3) * 100}%"></div>
  </div>

  <!-- Top controls: lang + theme -->
  <div class="top-controls">
    <div class="lang-wrapper-sm">
      <svg class="globe-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
           stroke-linecap="round" stroke-linejoin="round">
        <circle cx="12" cy="12" r="10"/>
        <line x1="2" y1="12" x2="22" y2="12"/>
        <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
      </svg>
      <select bind:value={$currentLang} class="lang-select-sm">
        {#each LANGUAGES as lang}
          <option value={lang.code}>{lang.label}</option>
        {/each}
      </select>
    </div>
    <button class="theme-btn" on:click={toggleTheme}>
      {#if $theme === "light"}🌙{:else}☀️{/if}
    </button>
  </div>

  <div class="onboarding-inner">
    <!-- Header -->
    <div class="onb-header">
      <div class="onb-logo">
        <img src="/logo.png" alt="Crypto AutoPay" width="32" height="32" style="border-radius:6px"/>
        <span class="onb-appname">Crypto AutoPay</span>
      </div>
      <div class="step-indicator">
        {#if restoring}{$t.restoreTitle} · {/if}{$t.step} {step}/3 —
        {#if step === 1}{$t.stepPassword}
        {:else if step === 2}{$t.stepSeed}
        {:else}{$t.stepBackup}
        {/if}
      </div>
    </div>

    <!-- ======================== STEP 1: Password ======================== -->
    {#if step === 1}
      <div class="step-content card">
        <div class="step-header-row">
          <button class="btn-back" on:click={goBack}>← {$t.back}</button>
          <h2>{$t.stepPassword}</h2>
          <span></span>
        </div>
        <p class="step-desc text-muted">{restoring ? $t.restorePasswordDesc : $t.stepPasswordDesc}</p>

        <label>
          {$t.masterPassword}
          <!-- svelte-ignore a11y-autofocus -->
          <input type="password" bind:value={password} placeholder={$t.masterPasswordPlaceholder} autocomplete="new-password" autofocus
            on:keydown={e => e.key === "Enter" && document.querySelector('#onb-confirm-pw')?.focus()} />
          <span class="pw-hint" class:pw-hint-ok={password.length >= 12}>{$t.passwordMinHint} ({Math.min(password.length, 12)}/12)</span>
        </label>
        <label>
          {$t.confirmPassword}
          <input id="onb-confirm-pw" type="password" bind:value={passwordConfirm} placeholder={$t.confirmPasswordPlaceholder} autocomplete="new-password"
            on:keydown={e => e.key === "Enter" && goStep2()} />
        </label>

        {#if passwordError}
          <div class="error-msg">{passwordError}</div>
        {/if}

        <div class="warning-box">{$t.passwordWarning}</div>

        <button class="btn-primary btn-full" on:click={goStep2}>{$t.continue}</button>
      </div>
    {/if}

    <!-- ======================== STEP 2: Seed ======================== -->
    {#if step === 2}
      <div class="step-content card">
        <div class="step-header-row">
          <button class="btn-back" on:click={goBack}>← {$t.back}</button>
          <h2>{$t.stepSeed}</h2>
          <span></span>
        </div>

        {#if restoring}
          <div class="info-box info-green">
            <div class="info-box-title">{$t.restoreTitle}</div>
            <p>{$t.restoreDesc}</p>
          </div>
        {:else}
          <p class="step-desc text-muted">{$t.stepSeedDesc}</p>
        {/if}

        <!-- 2 XMR security info -->
        <div class="info-box">
          <div class="info-box-title">🔒 {$t.seedLimit}</div>
          <p>{$t.seedLimitDetail}</p>
        </div>

        {#if !restoring}
          <div class="seed-display">
            {#if seedLoading}
              <div class="seed-loading">
                <span class="spinner"></span>
                {$t.seedGenerating}
              </div>
            {:else if seedGenError}
              <div class="error-msg">{$t.seedGenFailed}</div>
            {:else}
              <div class="seed-words">{generatedSeed}</div>
              <p class="seed-note">{$t.seedWriteDown}</p>
            {/if}
          </div>
        {:else}
          <label>
            {$t.seedPhrase}
            <textarea
              bind:value={importedSeed}
              placeholder={$t.seedPhrasePlaceholder}
              rows="3"
              class:textarea-error={importSeedError}
              class:textarea-ok={importSeedValid}
              spellcheck="false"
              autocomplete="off"
              autocorrect="off"
            ></textarea>
          </label>
          {#if importSeedError}
            <div class="error-msg">{importSeedError}</div>
          {:else if importSeedValid}
            <div class="success-msg">{$t.seedWordsOk}</div>
          {/if}

          <div class="restore-date">
            <span class="restore-date-label">{$t.restoreDateLabel}</span>
            <div class="restore-date-row">
              <select bind:value={restoreMonth} disabled={restoreDateUnknown} aria-label={$t.restoreDateMonth}>
                <option value="" disabled>{$t.restoreDateMonth}</option>
                {#each monthNames as name, i}<option value={String(i)}>{name}</option>{/each}
              </select>
              <select bind:value={restoreYear} disabled={restoreDateUnknown} aria-label={$t.restoreDateYear}>
                <option value="" disabled>{$t.restoreDateYear}</option>
                {#each YEARS as y}<option value={String(y)}>{y}</option>{/each}
              </select>
            </div>
            <label class="check-item">
              <input type="checkbox" bind:checked={restoreDateUnknown} />
              <span>{$t.restoreDateUnknown}</span>
            </label>
            <small class="text-muted">{$t.restoreDateHint}</small>
          </div>
        {/if}

        <button
          class="btn-primary btn-full"
          on:click={goStep3}
          disabled={restoring ? !(importSeedValid && restoreDateSet) : (seedLoading || seedGenError)}
        >{$t.continue}</button>
      </div>
    {/if}

    <!-- ======================== STEP 3: Backup + seed verification ======================== -->
    {#if step === 3}
      <div class="step-content card">
        <div class="step-header-row">
          <button class="btn-back" on:click={goBack}>← {$t.back}</button>
          <h2>{$t.stepBackup}</h2>
          <span></span>
        </div>

        <div class="checklist">
          <!-- Seed paper check -->
          <div class="check-item-verify">
            {#if !restoring}
              <!-- New seed: quiz to confirm user wrote it down -->
              {#if verifyPassed}
                <div class="verify-ok">
                  <span class="verify-check">✓</span>
                  <span>{$t.checkPaperSeed}</span>
                  <span class="verify-proof text-muted">{fmt($t.verifyWordProof, { n: verifyIndex, word: expectedWord })}</span>
                </div>
              {:else}
                <div class="verify-challenge">
                  <p class="verify-prompt">
                    {$t.verifyPromptBefore}
                    <strong>{fmt($t.verifyPromptStrong, { n: verifyIndex })}</strong> {$t.verifyPromptAfter}
                  </p>
                  <div class="verify-input-row">
                    <input
                      bind:value={verifyInput}
                      placeholder={fmt($t.verifyPlaceholder, { n: verifyIndex })}
                      on:keydown={e => e.key === "Enter" && checkWord()}
                      class:input-error={verifyError}
                      autocomplete="off"
                      spellcheck="false"
                    />
                    <button class="btn-primary" style="padding:9px 16px;font-size:13px" on:click={checkWord}>
                      {$t.verifyButton}
                    </button>
                  </div>
                  {#if verifyError}
                    <p class="error-msg">{$t.verifyWrong}</p>
                  {/if}
                </div>
              {/if}
            {:else}
              <!-- Import/restore: seed already known, no quiz needed -->
              <label class="check-item">
                <input type="checkbox" bind:checked={checkPaperSeed} />
                <span>{$t.checkPaperSeed}</span>
              </label>
            {/if}
          </div>

          <label class="check-item">
            <input type="checkbox" bind:checked={checkPaperPassword} />
            <span>{$t.checkPaperPassword}</span>
          </label>
          <label class="check-item">
            <input type="checkbox" bind:checked={checkLimit} />
            <span>{$t.checkLimit}</span>
          </label>
        </div>

        {#if finishError}
          <div class="error-msg">{finishError}</div>
        {/if}

        <button
          class="btn-primary btn-full"
          disabled={!verifyPassed || !checkPaperSeed || !checkPaperPassword || !checkLimit || finishLoading}
          on:click={finish}
        >
          {#if finishLoading}
            <span class="spinner"></span> {$t.walletCreating}
          {:else}
            🚀 {$t.launchButton}
          {/if}
        </button>
      </div>
    {/if}
  </div>
</div>

<style>
  .onboarding {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: var(--bg);
    padding: 40px 16px 24px;
    position: relative;
    overflow-y: auto;
  }

  .progress-bar {
    position: fixed; top: 0; left: 0; right: 0; height: 3px;
    background: var(--border); z-index: 10;
  }
  .progress-fill {
    height: 100%; background: var(--accent); transition: width .4s ease;
  }

  /* Top controls: lang + theme */
  .top-controls {
    position: fixed; top: 12px; right: 16px;
    display: flex; align-items: center; gap: 8px; z-index: 20;
  }
  .lang-wrapper-sm {
    display: flex; align-items: center; gap: 5px;
    background: var(--bg-card); border: 1px solid var(--border);
    border-radius: 7px; padding: 5px 9px;
  }
  .globe-sm { width: 13px; height: 13px; color: var(--text-muted); flex-shrink: 0; }
  .lang-select-sm {
    border: none; background: transparent; color: var(--text);
    font-size: 12px; cursor: pointer; outline: none;
    -webkit-appearance: none; appearance: none;
  }
  .lang-select-sm option { background: var(--bg-card); color: var(--text); }
  .theme-btn {
    background: var(--bg-card); border: 1px solid var(--border);
    border-radius: 7px; padding: 5px 9px; font-size: 15px; cursor: pointer;
  }

  .onboarding-inner {
    width: 100%; max-width: 480px; display: flex; flex-direction: column; gap: 18px;
  }

  .onb-header { display: flex; flex-direction: column; align-items: center; gap: 8px; }
  .onb-logo { display: flex; align-items: center; gap: 9px; }
  .onb-appname { font-size: 15px; font-weight: 700; }
  .step-indicator { font-size: 11px; color: var(--text-muted); }

  /* Step header row with back button */
  .step-header-row {
    display: flex; align-items: center; justify-content: space-between;
  }
  .step-header-row h2 { margin: 0; }
  .btn-back {
    background: transparent; border: none; color: var(--text-muted);
    font-size: 12px; cursor: pointer; padding: 4px 0;
  }
  .btn-back:hover { color: var(--text); }

  .step-content {
    padding: 22px; display: flex; flex-direction: column; gap: 14px;
  }
  .step-desc { font-size: 13px; }

  .error-msg {
    background: var(--red-bg); color: var(--red);
    padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px;
  }

  .warning-box {
    background: var(--orange-bg); color: var(--orange);
    border-left: 3px solid var(--orange);
    padding: 10px 14px; border-radius: var(--radius-sm); font-size: 13px; line-height: 1.6;
  }

  .info-box {
    background: var(--accent-light); border-left: 3px solid var(--accent);
    padding: 10px 14px; border-radius: var(--radius-sm);
    display: flex; flex-direction: column; gap: 5px;
  }
  .info-green { background: var(--green-bg); border-color: var(--green); }
  .info-box-title { font-weight: 700; font-size: 12px; color: var(--accent); }
  .info-green .info-box-title { color: var(--green); }
  .info-box p { font-size: 12px; color: var(--text); line-height: 1.6; }

  .seed-display {
    background: var(--bg-sidebar); border: 1px solid var(--border);
    border-radius: var(--radius-sm); padding: 13px;
    display: flex; flex-direction: column; gap: 6px;
  }
  .seed-words {
    font-family: "Courier New", monospace; font-size: 12.5px;
    color: var(--text); word-spacing: 5px; line-height: 1.9;
  }
  .seed-note { font-size: 10px; color: var(--orange); }

  .btn-full { width: 100%; padding: 13px; font-size: 14px; }

  /* ---- Seed word verification ---- */
  .checklist { display: flex; flex-direction: column; gap: 12px; }

  .check-item-verify {
    background: var(--bg-sidebar); border: 1px solid var(--border);
    border-radius: var(--radius-sm); padding: 12px 14px;
  }

  .verify-challenge { display: flex; flex-direction: column; gap: 8px; }

  .verify-prompt { font-size: 12.5px; color: var(--text); line-height: 1.6; margin: 0; }

  .verify-input-row {
    display: flex; gap: 8px; align-items: center;
  }
  .verify-input-row input {
    flex: 1; font-size: 13px; padding: 8px 12px;
    font-family: "Courier New", monospace; letter-spacing: 0.05em;
  }
  input.input-error { border-color: var(--red); }

  .verify-ok {
    display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
    font-size: 12.5px; color: var(--text);
  }
  .verify-check {
    width: 22px; height: 22px; background: var(--green); color: white;
    border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-size: 13px; font-weight: 700; flex-shrink: 0;
  }
  .verify-proof { font-size: 10.5px; font-style: italic; }

  .check-item {
    display: flex; align-items: flex-start; gap: 10px;
    cursor: pointer; font-size: 13px; color: var(--text);
    flex-direction: row;
  }
  .check-item input[type="checkbox"] {
    width: 16px; height: 16px; margin-top: 2px;
    flex-shrink: 0; accent-color: var(--accent); cursor: pointer;
  }

  button:disabled { opacity: 0.4; cursor: not-allowed; }

  textarea.textarea-error { border-color: var(--red); }
  textarea.textarea-ok    { border-color: var(--green); }
  .success-msg {
    background: var(--green-bg); color: var(--green);
    padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px;
  }

  .seed-loading {
    display: flex; align-items: center; gap: 8px;
    font-size: 12.5px; color: var(--text-muted);
    min-height: 48px;
  }

  .spinner {
    width: 14px; height: 14px;
    border: 2px solid var(--border);
    border-top-color: var(--accent);
    border-radius: 50%;
    display: inline-block;
    animation: spin 0.7s linear infinite;
    flex-shrink: 0;
  }

  @keyframes spin { to { transform: rotate(360deg); } }
  .restore-date { display: flex; flex-direction: column; gap: 8px; }
  .restore-date-label { font-size: 13px; font-weight: 600; }
  .restore-date-row { display: flex; gap: 8px; }
  .restore-date-row select { flex: 1; }
  .restore-date small { font-size: 11.5px; line-height: 1.5; }
  .pw-hint { display: block; font-size: 12px; color: var(--text-muted); margin-top: 4px; }
  .pw-hint-ok { color: var(--green); }
</style>
